'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { CallPanel, discModeOf } from './call-panel';
import { CALL_TITLE, NOTES, TODOS, TRANSCRIPT } from './data';
import { NotesPage } from './notes-page';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  SHARE_MS,
  type CallStatus,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function announcementOf(status: CallStatus, latestTodo: string | undefined) {
  if (status === 'ended') {
    return 'Call ended. The page is now a summary you can copy or share.';
  }
  if (latestTodo) {
    return `To-do added: ${latestTodo}`;
  }
  return '';
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

export default function AgentChat04() {
  const { ref, isInView, isAutoplaying, state, act, pressed, restart } =
    useSession(SESSION);
  const { schedule } = useTimeouts();
  const lines = TRANSCRIPT.slice(0, state.linesShown);
  const notes = NOTES.slice(0, state.notesShown);
  const todos = TODOS.slice(0, state.todosShown);
  const latestLine = lines.at(-1);
  const speaker = latestLine?.speaker ?? null;
  const mode = discModeOf(state.status, state.isMuted, speaker);
  const isEnded = state.status === 'ended';
  const latestTodo = todos.at(-1)?.text;
  const announcement = announcementOf(state.status, latestTodo);
  const message = spokenUnless(isAutoplaying, announcement);
  const canCallAgain = isEnded && !isAutoplaying;

  function share() {
    act({ type: 'sharing' });
    schedule(() => act({ type: 'shared' }), SHARE_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full p-3 @3xl:p-6'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-3 @3xl:flex-row @3xl:items-start'>
          <div className='@3xl:w-80 @3xl:shrink-0'>
            <CallPanel
              title={CALL_TITLE}
              status={state.status}
              mode={mode}
              isMuted={state.isMuted}
              lines={lines}
              startedAt={state.startedAt}
              endedAt={state.endedAt}
              isActive={isInView}
              pressed={pressed}
              onToggleMute={() => act({ type: 'muted' })}
              onEnd={() => act({ type: 'ended' })}
              footer={
                <ReplayButton
                  isShown={canCallAgain}
                  onReplay={restart}
                  label='Call again'
                />
              }
            />
          </div>
          <NotesPage
            title={CALL_TITLE}
            notes={notes}
            todos={todos}
            doneBy={state.doneBy}
            isEnded={isEnded}
            share={state.share}
            onToggleTodo={(id) => act({ type: 'toggled', id })}
            onShare={share}
          />
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useEffect, useRef } from 'react';

import {
  AudioLinesIcon,
  MicIcon,
  MicOffIcon,
  PhoneOffIcon,
} from '@/registry/ndeko/lib/icons';
import { formatClock, spokenClockOf } from '@/registry/ndeko/lib/media-clock';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { speechLevelAt } from '@/registry/ndeko/lib/speech-envelope';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { useLiveNow } from '@/registry/ndeko/ui/live-duration';

import type { Speaker, TranscriptLine } from './data';
import type { CallStatus } from './session';

export type DiscMode =
  'connecting' | 'listening' | 'speaking' | 'muted' | 'ended';

const MODE_WORD: Record<DiscMode, string> = {
  connecting: 'Connecting',
  listening: 'Listening',
  speaking: 'Speaking',
  muted: 'Muted',
  ended: 'Call ended',
};

const MODE_INTENSITY: Record<DiscMode, number> = {
  connecting: 0,
  listening: 0.65,
  speaking: 1,
  muted: 0.04,
  ended: 0,
};

/** How much of the gap to the new level is closed on each frame, so the disc breathes instead of jumping. */
const LEVEL_EASING = 0.16;

const HALO_REACH = 0.22;

const OUTER_REACH = 0.42;

export function discModeOf(
  status: CallStatus,
  isMuted: boolean,
  speaker: Speaker | null
): DiscMode {
  if (status === 'ended') {
    return 'ended';
  }
  if (status === 'ringing') {
    return 'connecting';
  }
  if (isMuted) {
    return 'muted';
  }
  if (speaker === 'assistant') {
    return 'speaking';
  }
  return 'listening';
}

function ModeGlyph({ mode }: { mode: DiscMode }) {
  if (mode === 'speaking') {
    return <AudioLinesIcon className='size-7' />;
  }
  if (mode === 'muted') {
    return <MicOffIcon className='size-7' />;
  }
  if (mode === 'ended') {
    return <PhoneOffIcon className='size-7' />;
  }
  return <MicIcon className='size-7' />;
}

function coreToneOf(mode: DiscMode) {
  const isQuiet = mode === 'ended' || mode === 'muted';
  if (isQuiet) {
    return '[--gem:var(--muted-foreground)]';
  }
  return '[--gem:var(--primary)]';
}

type VoiceDiscProps = {
  mode: DiscMode;
  /** False while the block is off screen or the call is over: the disc stops drawing. */
  isActive: boolean;
};

/** The level is written to the two halos on each frame, so React never re-renders for it. */
export function VoiceDisc({ mode, isActive }: VoiceDiscProps) {
  const haloRef = useRef<HTMLSpanElement>(null);
  const outerRef = useRef<HTMLSpanElement>(null);
  const intensityRef = useRef(MODE_INTENSITY[mode]);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    intensityRef.current = MODE_INTENSITY[mode];
  }, [mode]);

  useEffect(() => {
    const halo = haloRef.current;
    const outer = outerRef.current;
    const shouldDraw = isActive && !shouldReduceMotion;
    if (!shouldDraw) {
      return;
    }
    if (!halo || !outer) {
      return;
    }
    const startedAt = performance.now();
    let level = 0;
    let frame = 0;

    function draw(now: number) {
      if (!halo || !outer) {
        return;
      }
      const voice = speechLevelAt(now - startedAt, 2.4);
      const target = voice * intensityRef.current;
      level += (target - level) * LEVEL_EASING;
      const haloScale = 1 + level * HALO_REACH;
      const outerScale = 1 + level * OUTER_REACH;
      halo.style.transform = `scale(${haloScale})`;
      outer.style.transform = `scale(${outerScale})`;
      frame = requestAnimationFrame(draw);
    }

    frame = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(frame);
      halo.style.transform = '';
      outer.style.transform = '';
    };
  }, [isActive, shouldReduceMotion]);

  return (
    <div className='relative flex size-32 shrink-0 items-center justify-center @3xl:size-40'>
      <span
        ref={outerRef}
        aria-hidden='true'
        className='bg-primary/[0.07] absolute inset-4 rounded-full'
      />
      <span
        ref={haloRef}
        aria-hidden='true'
        className='bg-primary/[0.12] absolute inset-7 rounded-full'
      />
      <span
        className={cn(
          'gem-plate relative flex size-16 items-center justify-center rounded-full transition-[background-image] duration-300 @3xl:size-20',
          coreToneOf(mode)
        )}
      >
        <Swap swapKey={mode}>
          <ModeGlyph mode={mode} />
        </Swap>
      </span>
    </div>
  );
}

function elapsedOfCall(
  startedAt: number | null,
  endedAt: number | null,
  now: number
) {
  if (startedAt === null) {
    return 0;
  }
  const end = endedAt ?? now;
  return Math.max(0, end - startedAt);
}

type CallClockProps = {
  startedAt: number | null;
  endedAt: number | null;
};

/** Only this text re-renders each second. */
function CallClock({ startedAt, endedAt }: CallClockProps) {
  const isRunning = startedAt !== null && endedAt === null;
  const now = useLiveNow(1000, isRunning);
  const elapsed = elapsedOfCall(startedAt, endedAt, now);

  return (
    <span className='text-muted-foreground inline-block w-10 text-center text-[13px] tabular-nums'>
      <span aria-hidden='true'>{formatClock(elapsed)}</span>
      <span className='sr-only'>{spokenClockOf(elapsed)}</span>
    </span>
  );
}

const SPEAKER_WORD: Record<Speaker, string> = {
  person: 'You',
  assistant: 'Assistant',
};

function lineToneOf(isLatest: boolean) {
  if (isLatest) {
    return 'opacity-100';
  }
  return 'opacity-45';
}

function Transcript({ lines }: { lines: TranscriptLine[] }) {
  const shouldReduceMotion = useReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const recent = lines.slice(-3);
  const latest = recent.at(-1);

  return (
    <div className='flex h-36 w-full flex-col justify-end overflow-hidden'>
      {recent.length === 0 && (
        <p className='text-muted-foreground m-auto text-center text-[13px]'>
          What is said shows up here
        </p>
      )}
      <ol aria-label='Transcript' className='flex flex-col'>
        <AnimatePresence initial={false}>
          {recent.map((line) => (
            <motion.li
              key={line.id}
              className='overflow-hidden'
              {...rowPresence}
            >
              <p
                className={cn(
                  'pb-2 text-[13px] leading-snug transition-opacity duration-300',
                  lineToneOf(line === latest)
                )}
              >
                <span className='text-muted-foreground'>
                  {SPEAKER_WORD[line.speaker]}
                </span>{' '}
                {line.text}
              </p>
            </motion.li>
          ))}
        </AnimatePresence>
      </ol>
    </div>
  );
}

function muteLabelOf(isMuted: boolean) {
  if (isMuted) {
    return 'Unmute';
  }
  return 'Mute';
}

function pressedDestructiveOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-destructive/85';
  }
  return undefined;
}

type CallPanelProps = {
  title: string;
  status: CallStatus;
  mode: DiscMode;
  isMuted: boolean;
  lines: TranscriptLine[];
  startedAt: number | null;
  endedAt: number | null;
  isActive: boolean;
  pressed: string | null;
  onToggleMute: () => void;
  onEnd: () => void;
  footer?: React.ReactNode;
};

export function CallPanel({
  title,
  status,
  mode,
  isMuted,
  lines,
  startedAt,
  endedAt,
  isActive,
  pressed,
  onToggleMute,
  onEnd,
  footer,
}: CallPanelProps) {
  const isLive = status === 'live';
  const isEnded = status === 'ended';
  const muteLabel = muteLabelOf(isMuted);

  return (
    <section
      aria-label='Call'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col items-center gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <div className='flex w-full items-center justify-between gap-3'>
        <h2 className='min-w-0 truncate text-sm font-medium'>{title}</h2>
        <CallClock startedAt={startedAt} endedAt={endedAt} />
      </div>
      <VoiceDisc mode={mode} isActive={isActive && isLive} />
      <Swap swapKey={mode} className='text-[13px] font-medium'>
        {MODE_WORD[mode]}
      </Swap>
      <Transcript lines={lines} />
      <div className='flex h-9 items-center gap-2'>
        {!isEnded && (
          <Button
            type='button'
            variant='outline'
            size='lg'
            aria-pressed={isMuted}
            disabled={!isLive}
            onClick={onToggleMute}
          >
            <Swap swapKey={muteLabel}>
              {isMuted && <MicOffIcon />}
              {!isMuted && <MicIcon />}
            </Swap>
            {muteLabel}
          </Button>
        )}
        {!isEnded && (
          <Button
            type='button'
            variant='destructive'
            size='lg'
            disabled={!isLive}
            onClick={onEnd}
            className={pressedDestructiveOf(pressed === 'end')}
          >
            <PhoneOffIcon />
            End call
          </Button>
        )}
        {isEnded && footer}
      </div>
    </section>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { CalendarIcon, FeatherIcon } from '@/registry/ndeko/lib/icons';
import {
  EASE_OUT_STRONG,
  risePresenceOf,
  rowPresenceOf,
} from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import { summaryTextOf, type Note, type Owner, type Todo } from './data';
import type { DoneBy } from './session';

const CHECK_PATH = 'M2.6 6.4 4.9 8.7 9.5 3.6';

const DRAW = { duration: 0.28, ease: EASE_OUT_STRONG, delay: 0.08 };

const SHARE_LABELS: Record<MorphState, string> = {
  idle: 'Share with the team',
  busy: 'Sharing',
  done: 'Shared',
};

function strokeStartOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return { pathLength: 1 };
  }
  return { pathLength: 0 };
}

/** The tick of a finished to-do draws itself, whoever finished it. */
function DrawnCheck() {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className='chip-3d inline-flex size-[18px] items-center justify-center rounded-full [--chip:var(--primary)]'>
      <svg aria-hidden='true' viewBox='0 0 12 12' className='size-3'>
        <motion.path
          d={CHECK_PATH}
          fill='none'
          stroke='currentColor'
          strokeWidth='1.9'
          strokeLinecap='round'
          strokeLinejoin='round'
          initial={strokeStartOf(shouldReduceMotion)}
          animate={{ pathLength: 1 }}
          transition={DRAW}
        />
      </svg>
    </span>
  );
}

function OwnerMark({ owner }: { owner: Owner }) {
  if (owner.avatar === null) {
    return (
      <span
        aria-hidden='true'
        className='gem-plate inline-flex size-4 items-center justify-center rounded-full [--gem:var(--primary)]'
      >
        <FeatherIcon className='size-2.5' />
      </span>
    );
  }
  return (
    <Avatar className='size-4'>
      <AvatarImage src={owner.avatar} alt='' />
      <AvatarFallback className='text-[8px]'>{owner.initials}</AvatarFallback>
    </Avatar>
  );
}

const PILL =
  'bg-foreground/[0.05] inline-flex h-6 shrink-0 items-center gap-1.5 rounded-full px-2 text-xs';

function todoTextOf(isDone: boolean) {
  if (isDone) {
    return 'text-muted-foreground line-through';
  }
  return 'text-foreground';
}

type TodoRowProps = {
  todo: Todo;
  doneBy: DoneBy | undefined;
  onToggle: (id: string) => void;
};

function TodoRow({ todo, doneBy, onToggle }: TodoRowProps) {
  const isDone = doneBy !== undefined;
  const isByAssistant = doneBy === 'assistant';

  return (
    <div className='flex flex-wrap items-start gap-x-2.5 gap-y-1 py-1.5'>
      <button
        type='button'
        role='checkbox'
        aria-checked={isDone}
        aria-label={todo.text}
        onClick={() => onToggle(todo.id)}
        className='focus-visible:ring-ring/40 mt-0.5 flex size-[18px] shrink-0 cursor-pointer items-center justify-center rounded-full outline-none focus-visible:ring-[3px] active:scale-[0.97]'
      >
        {isDone && <DrawnCheck />}
        {!isDone && (
          <span className='hairline-ring ring-foreground/30 hover:ring-foreground/60 size-[18px] rounded-full transition-shadow duration-150' />
        )}
      </button>
      <div className='flex min-w-40 flex-1 flex-col'>
        <span
          className={cn(
            'text-[13px] leading-[1.375rem] transition-colors duration-200',
            todoTextOf(isDone)
          )}
        >
          {todo.text}
        </span>
        <Fold open={isByAssistant}>
          <span className='text-muted-foreground flex h-6 items-center gap-2 text-xs'>
            Done by assistant
            <button
              type='button'
              onClick={() => onToggle(todo.id)}
              className='text-primary-ink focus-visible:ring-ring/25 cursor-pointer rounded-sm font-medium underline-offset-4 outline-none hover:underline focus-visible:ring-[3px]'
            >
              Undo
            </button>
          </span>
        </Fold>
      </div>
      <div className='flex items-center gap-1.5 ps-7 @md:ps-0'>
        <span className={PILL}>
          <OwnerMark owner={todo.owner} />
          {todo.owner.name}
        </span>
        <span className={cn(PILL, 'text-muted-foreground tabular-nums')}>
          <CalendarIcon className='size-3' />
          {todo.due}
        </span>
      </div>
    </div>
  );
}

function modeWordOf(isEnded: boolean) {
  if (isEnded) {
    return 'Summary of the call';
  }
  return 'Live notes';
}

function EmptyLine({ text }: { text: string }) {
  return <p className='text-muted-foreground py-1.5 text-[13px]'>{text}</p>;
}

type NotesPageProps = {
  title: string;
  notes: Note[];
  todos: Todo[];
  doneBy: Record<string, DoneBy>;
  isEnded: boolean;
  share: MorphState;
  onToggleTodo: (id: string) => void;
  onShare: () => void;
};

export function NotesPage({
  title,
  notes,
  todos,
  doneBy,
  isEnded,
  share,
  onToggleTodo,
  onShare,
}: NotesPageProps) {
  const shouldReduceMotion = useReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const risePresence = risePresenceOf(shouldReduceMotion);
  const modeWord = modeWordOf(isEnded);
  const hasNotes = notes.length > 0;
  const hasTodos = todos.length > 0;

  return (
    <section
      aria-label='Notes'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-w-0 flex-1 flex-col gap-5 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @3xl:p-6'
    >
      <header className='flex min-h-9 flex-wrap items-center justify-between gap-2'>
        <div className='flex flex-col'>
          <h2 className='text-lg leading-tight font-semibold'>{title}</h2>
          <Swap swapKey={modeWord} className='text-muted-foreground text-xs'>
            {modeWord}
          </Swap>
        </div>
        <AnimatePresence initial={false}>
          {isEnded && (
            <motion.div
              key='actions'
              className='flex items-center gap-1.5'
              {...risePresence}
            >
              <CopyButton
                text={summaryTextOf(notes, todos)}
                label='Copy the summary'
              />
              <MorphButton
                type='button'
                size='sm'
                variant='outline'
                state={share}
                labels={SHARE_LABELS}
                onClick={onShare}
              />
            </motion.div>
          )}
        </AnimatePresence>
      </header>

      <div className='flex flex-col gap-1'>
        <h3 className='text-muted-foreground text-xs'>Notes</h3>
        {!hasNotes && (
          <EmptyLine text='Notes are written here as they are said' />
        )}
        <ul className='flex flex-col'>
          <AnimatePresence initial={false}>
            {notes.map((note) => (
              <motion.li
                key={note.id}
                className='overflow-hidden'
                {...rowPresence}
              >
                <p className='flex gap-2.5 py-1.5 text-[13px] leading-snug'>
                  <span
                    aria-hidden='true'
                    className='bg-foreground/40 mt-[7px] size-1 shrink-0 rounded-full'
                  />
                  {note.text}
                </p>
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </div>

      <div className='flex flex-col gap-1'>
        <h3 className='text-muted-foreground text-xs'>To-dos</h3>
        {!hasTodos && (
          <EmptyLine text='To-dos get an owner and a date when they come up' />
        )}
        <ul className='flex flex-col'>
          <AnimatePresence initial={false}>
            {todos.map((todo) => (
              <motion.li
                key={todo.id}
                className='-mx-1 overflow-hidden px-1'
                {...rowPresence}
              >
                <TodoRow
                  todo={todo}
                  doneBy={doneBy[todo.id]}
                  onToggle={onToggleTodo}
                />
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </div>
    </section>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

export type CallStatus = 'ringing' | 'live' | 'ended';

export type DoneBy = 'assistant' | 'person';

export type VoiceState = {
  status: CallStatus;
  isMuted: boolean;
  linesShown: number;
  notesShown: number;
  todosShown: number;
  /** Who ticked each finished to-do. */
  doneBy: Record<string, DoneBy>;
  startedAt: number | null;
  endedAt: number | null;
  share: 'idle' | 'busy' | 'done';
};

export type VoiceAction =
  | { type: 'started' }
  | { type: 'line' }
  | { type: 'note' }
  | { type: 'todo' }
  | { type: 'did'; id: string }
  | { type: 'toggled'; id: string }
  | { type: 'muted' }
  | { type: 'ended' }
  | { type: 'sharing' }
  | { type: 'shared' }
  | { type: 'batch'; actions: VoiceAction[] };

type Step = SessionStep<VoiceState, VoiceAction>;

export const INITIAL: VoiceState = {
  status: 'ringing',
  isMuted: false,
  linesShown: 0,
  notesShown: 0,
  todosShown: 0,
  doneBy: {},
  startedAt: null,
  endedAt: null,
  share: 'idle',
};

function without(doneBy: Record<string, DoneBy>, id: string) {
  const rest = { ...doneBy };
  delete rest[id];
  return rest;
}

function toggled(state: VoiceState, id: string): VoiceState {
  const isDone = state.doneBy[id] !== undefined;
  if (isDone) {
    return { ...state, doneBy: without(state.doneBy, id) };
  }
  return { ...state, doneBy: { ...state.doneBy, [id]: 'person' } };
}

function ended(state: VoiceState, now: number): VoiceState {
  if (state.status !== 'live') {
    return state;
  }
  return { ...state, status: 'ended', endedAt: now };
}

function shared(state: VoiceState): VoiceState {
  if (state.share !== 'busy') {
    return state;
  }
  return { ...state, share: 'done' };
}

/** Once the call has ended nothing more is said or written. */
function whileLive(state: VoiceState, next: VoiceState) {
  if (state.status === 'live') {
    return next;
  }
  return state;
}

export function applyAt(
  state: VoiceState,
  action: VoiceAction,
  now: number
): VoiceState {
  switch (action.type) {
    case 'started':
      return { ...state, status: 'live', startedAt: now };
    case 'line':
      return whileLive(state, { ...state, linesShown: state.linesShown + 1 });
    case 'note':
      return whileLive(state, { ...state, notesShown: state.notesShown + 1 });
    case 'todo':
      return whileLive(state, { ...state, todosShown: state.todosShown + 1 });
    case 'did': {
      const doneBy: Record<string, DoneBy> = {
        ...state.doneBy,
        [action.id]: 'assistant',
      };
      return whileLive(state, { ...state, doneBy });
    }
    case 'toggled':
      return toggled(state, action.id);
    case 'muted':
      return { ...state, isMuted: !state.isMuted };
    case 'ended':
      return ended(state, now);
    case 'sharing':
      return { ...state, share: 'busy' };
    case 'shared':
      return shared(state);
    case 'batch': {
      let next = state;
      for (const inner of action.actions) {
        next = applyAt(next, inner, now);
      }
      return next;
    }
  }
}

export function reducer(state: VoiceState, action: VoiceAction) {
  return applyAt(state, action, Date.now());
}

function frame(after: number, actions: VoiceAction[]): Step {
  return { after, action: { type: 'batch', actions } };
}

