export function summaryTextOf(notes: Note[], todos: Todo[]) {
  const noteLines = notes.map((note) => `- ${note.text}`);
  const todoLines = todos.map(
    (todo) => `- ${todo.text} (${todo.owner.name}, ${todo.due})`
  );
